arguments.command:
mkdir -p /app/out && cd /app && cat > /app/run.py <<'E'
import csv,json,collections
W={};M=collections.Counter()
def add(w,month,kg,st):
    if st.strip().lower()!="delivered":return
    d=W.setdefault(w,{"shipments":0,"total_kg":0.0});d["shipments"]+=1;d["total_kg"]+=kg;M[month]+=1
for r in csv.DictReader(open("data/east.csv")):add("east",r["shipped"][:7],float(r["weight_kg"]),r["status"])
for r in csv.DictReader(open("data/west.csv"),delimiter=";"):
    d,m,y=r["shipped"].split(".");add("west",f"{y}-{m}",float(r["weight_lb"].replace(",","."))*0.45359237,r["status"])
for l in open("data/north.jsonl"):
    if l.strip():
        r=json.loads(l);add("north",r["shipped_at"][:7],r["weight_g"]/1000,r["status"])
for d in W.values():d["total_kg"]=round(d["total_kg"],2)
json.dump({"warehouses":dict(sorted(W.items())),"by_month":dict(sorted(M.items()))},open("out/summary.json","w"),indent=2)
E
python3 run.py && cat out/summary.json
echo '{"status":"success","summary":"Parsed the east, west and north exports, kept only delivered shipments, converted weights to kg, and wrote /app/out/summary.json."}' > STATUS.json

